SourceCode.Declaration:
/// <summary>
/// [executionId] is set on success - enqueued as a batch job, not run synchronously (unlike
/// export's `exportOpenJournals`), so the app polls it the same way it already polls a plain
/// `ImportFromPackage` execution id: the public `GetExecutionSummaryStatus`/`GetExecutionErrors`
/// OData actions, unchanged - only the trigger moved off the public REST action, not the status
/// check. See HSMobileOpsCountingService::importCounts's own doc comment.
/// </summary>
[DataContractAttribute]
class HSMobileOpsImportCountsResponse
{
    boolean success;
    str     errorCode;
    str     executionId;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('ExecutionId')]
public str parmExecutionId(str _value = executionId)
{
    executionId = _value;
    return executionId;
}
